[1615]="[ZM]弟子因繁杂庶务耽搁了修炼，如今寿元将尽，急需几颗紫色品质寿元丹以延长寿元",
[1616]="伸张正义",
[1617]="近日天云洲中有山匪作乱，其中甚至有一定修为，实为正道所不容，当伸张正义，给予惩戒",
[1618]="狂牛乱撞",
[1619]="一群发狂的牛妖在天云洲的平原上横冲直撞，为祸众生，望有能之士出手将其制服",
[1620]="炼体瓶颈",
