[1625]="灵石紧缺",
[1626]="提交100000灵石",
[1627]="[ZM]近日灵石消耗过度，不慎库存竟已见底，若可送来一批灵石用于周转，本宗必有酬谢",
[1628]="炼宝材料",
[1629]="提交20个天清花",
[1630]="[ZM]弟子正欲炼制法宝，查点库存时发现竟还缺几个材料，不知贵宗能否提供此物，本宗必有重酬",
[1631]="妖兽作乱",
[1632]="近日天云宗中有凶悍妖兽出没，致使本宗外出游历弟子人心惶惶，若能除掉此妖，本宗必有酬谢",
[1633]="医治弟子",
[1634]="提交5颗疗伤丹",
[1635]="[ZM]一名弟子意外身负重伤，急需几颗蓝色品质疗伤丹进行医治，若有能提供此物者，本宗必有酬谢",
[1636]="村庄遇袭",
[1637]="完成指定奇遇事件",
[1638]="据闻天云洲有一处村落遭受妖兽袭击，生灵涂炭，十分危急，贵宗可否派遣弟子前去一探究竟，解村民于倒悬之急",
[1639]="大补之物",
[1640]="南疆出现了一群毒虫，这可是大补之物，若能将其狩猎回来，定能让本门弟子十分高兴",
[1641]="提交10个土行之气",
[1642]="[ZM]一名土灵根弟子炼体遭遇瓶颈，急需土行之气以突破瓶颈，如有相赠者，本宗定有酬谢",
[1643]="矿石紧缺",
[1644]="提交60000矿石",
[1645]="[ZM]近日打算在门中建造一尊孔哥和孟哥的圣像，急需一批矿石用以建造，如有相赠者，愿孔哥和孟哥保佑你",
[1646]="传闻有一群魔修在南疆出没，其居心叵测，不可放任，赶紧代表孔哥和孟哥去消灭他们",
[1647]="精炼材料",
[1648]="提交100个凡品精炼石",
[1649]="工欲善其事必先利其器，[ZM]急需一批精炼石用于精炼装备，奈何门中库存不足，如有相赠者，本宗定有酬谢",
[1650]="虫群灾患",
[1651]="一大群飞虫在南疆肆掠，实在是怎么赶也赶不走，望有能之士伸出援手，将这群飞虫一举歼灭",
[1652]="提交20个荧光虫甲",
[1653]="近日门中弟子们正欲炼制法宝，查点库存时发现竟还缺几个荧光虫甲，如有可提供此材料者，本宗必有酬谢",
[1654]="妖兽暴动",
[1655]="近日南疆中有凶悍妖兽出没，致使本宗外出游历弟子人心惶惶，若能除掉此妖，本宗必有酬谢",
[1656]="宗门扩建",
[1657]="提交80000灵木",
[1658]="近日门中弟子勤于练武，打坏了不少木桩，急需一批灵木进行修复，得把木桩修得更结实一点",
[1659]="正邪相争",
[1660]="近日有一群邪修在南疆作乱，无恶不作，为所欲为，自古正邪不两立，必须将其降服，希望贵宗助本宗一臂之力",
[1661]="猿猴作乱",
[1662]="太岳山脉中有一群猿猴作乱，已多次袭击本门外出游历弟子，若能将其降服，本宗必有酬谢",
[1663]="玄铁紧缺",
[1664]="提交50000玄铁",
[1665]="门中弟子急需玄铁精炼法器，奈何库房中竟无库存，如有相赠者，本宗定有酬谢",
[1666]="虎啸山林",
[1667]="太岳山脉中有一群虎妖占山为王，使本门弟子无法靠近，若能将其降服，本宗必有酬谢",
[1668]="提交20个玉髓",
[1669]="传闻有一群魔修在太岳山脉出没，其居心叵测，不可放任，望有能者速速前去剿灭",
[1670]="草木成精",
[1671]="太岳山脉中有一群草木精怪吸收日月精华成精，到处作乱，若能将其降服，本宗必有酬谢",
[1672]="提交20个朱果",
[1673]="近日门中弟子欲炼制灵丹，结果发现还差一味材料，如果有可提供此材料者，本宗必有重谢",
[1674]="捕猎巨熊",
[1675]="太岳山脉中有一头凶猛的熊妖，其实力远超寻常妖兽，本宗已有多位弟子被其所伤，如能将其降服，本宗必有重酬",
[1676]="近日宗门急需扩建，需要大量灵木，奈何门中库存不足，如有相赠者，本宗定有酬谢",
[1677]="水妖作乱",
[1678]="近日天云洲中有水妖作乱，其借助水道神出鬼没，危害深远，若能将其降服，本宗必有酬谢",
[1679]="提交10个金行之气",
