[1681]="采集沧珠",
[1682]="[ZM]需要几颗沧珠以装点宗门，只有百年以上的蚌精可结出此物，若能击败蚌精采集沧珠归来，本宗必有酬谢",
[1683]="[ZM]近日矿石紧缺，炼器阁无矿石可炼，若能提供一批矿石以解燃眉之急，本宗必有酬谢",
[1684]="古怪傀儡",
[1685]="近日天云洲中出现一些古怪傀儡，这些傀儡自有灵性，肆意袭击修炼者，若能将其降服，本宗必有酬谢",
[1686]="提交20个玄鹤羽",
[1687]="妖兽暴乱",
[1688]="水患再生",
[1689]="天云洲中又生水患，恐怕又有水妖从中作梗，望有能之士出手相助，降服此作乱妖物",
[1690]="群狼袭扰",
[1691]="一群狼妖袭击了宗门附近的南疆部落，致使周围人心惶惶，若能将其降服，本宗必有酬谢",
