[1699]="好斗之士",
[1700]="近日有一群南疆勇士极其好斗，到处找宗门踢馆，称即分高下，亦决生死，本宗不想与其争斗，可否请贵宗出手将其教训一番",
[1701]="灵木紧缺",
[1702]="飞虫成灾",
