[1704]="捕捉虫王",
[1705]="一头丧魂蜈蚣在南疆现身，其上下浑身是宝，若能将其捕捉归来，定能使本宗实力大增",
[1706]="近日天山中有凶悍妖兽出没，致使本宗外出游历弟子人心惶惶，若能除掉此妖，本宗必有酬谢",
[1707]="提交10个寿元丹",
[1708]="冰枭袭人",
[1709]="近日有一群冰枭在天山出没，肆意袭击我宗游历弟子，若能将其降服，本宗必有酬谢",
[1710]="熊啸雪原",
[1711]="近日天山中有熊妖出没，其实力凶悍异常，难以降服，若能将其击败，本宗必有酬谢",
[1712]="提交10个水行之气",
[1713]="[ZM]一名水灵根弟子炼体遭遇瓶颈，急需水行之气以突破瓶颈，如有相赠者，必有酬谢",
[1714]="冰猿咆哮",
[1715]="近日天山中有一头冰猿出没，其实力高强，本宗已有多名弟子被其所伤，若能将其击败，本宗必有酬谢",
[1716]="工欲善其事必先利其器，[ZM]急需精炼石用于精炼装备，奈何门中库存不足，如有相赠者，本宗定有酬谢",
[1717]="提交20个寒铁",
[1718]="[ZM]弟子正欲炼制法宝，查点库存时发现竟还缺几块寒铁，不知贵宗能否提供此物，本宗必有重酬",
[1719]="雪域狼王",
[1720]="一头雪域狼王在此地占山为王，其实力远超寻常妖兽，本宗已有多位弟子被其所伤，若能将其击败，本宗必有重酬",
[1721]="近日有一群自诩正道之士，到处袭击本门弟子，若想与本门结交，便先去驱逐这群所谓的正道之士吧",
[1722]="劫掠富商",
[1723]="有一名富商正在运送货物经过太岳山脉，这是一个千载难逢的好机会，但其身旁还有一群修士担任护卫，必须将其击败，方能好好劫掠一番",
[1724]="教训家族",
[1725]="有一个修仙家族的修士不知天高地厚，竟敢招惹本宗，必须将其好生教训一番，让他们知道什么叫恶人自有恶人磨！",
[1726]="收服鬼物",
[1727]="近日本门弟子需要一些鬼物用以炼制法器，若能将鬼物收服归来，本宗必有酬谢",
[1728]="提交10个金阳参",
[1729]="[ZM]弟子正欲炼制法宝，查点库存时发现竟还缺一样材料，不知贵宗能否提供此物，本宗必有重酬",
[1730]="捕捉猴王",
[1731]="本宗还需捕捉一头老猴王以炼制法器，奈何其实力高强，本宗弟子奈何不得，若能将其捕捉回来，本宗必有重酬",
[1732]="收集毒虫",
[1733]="[ZM]需要一些毒虫以炼制毒物，若能将其捕捉回来，本宗必有酬谢",
[1734]="收集毒藤",
[1735]="提交20个幽罗蔓",
[1736]="[ZM]还需要一些毒藤以强化毒性，若能提供此毒藤，本宗必有酬谢",
[1737]="五毒俱全",
[1738]="毒物的毒性仍有不足，若要五毒俱全，蜈蚣毒液必不可少，若是捕捉一些蜈蚣归来，本宗定有酬谢",
[1739]="幽冥之物",
[1740]="提交20个幽冥灵骨",
[1741]="毒物自然是越毒越好，若能加入一些幽冥灵骨，毒性还能更上一层楼，如有相赠者，本宗定有酬谢",
[1742]="蜘魔毒液",
[1743]="五毒之物自然不可少了蜘蛛，若能捕捉一些紫魔蛛归来，本宗便可炼制出更恐怖的毒物",
[1744]="[ZM]近日沉迷炼毒，竟未察觉门中灵石接近耗尽，若可送来一批灵石用于周转，本宗必有酬谢",
[1745]="找人试毒",
[1746]="炼制好的毒物，若不能找人来试毒，可就太浪费了，正好近日有一群好斗的南疆勇士四处挑衅其他宗门，正好可以捉来试毒",
[1747]="药石难治",
[1748]="毒物不仅要致命，更要难治，方为上品。可否送来3颗蓝色品质的疗伤丹，一试此毒物是否药石难治",
[1749]="毒物不足",
[1750]="经过试验，此次炼制成的毒物仍有所不足，需要捕猎更多毒物，以完成此毒物的炼制",
[1751]="毒蛾粉末",
[1752]="传闻南疆有一只幻梦毒蛾，其粉末剧毒无比，乃是炼制毒物的无上至宝，若能将其捕捉回来，本宗定有重酬",
[1753]="兽潮余波",
[1754]="幽萤谷的兽潮仍有部分余孽，若不能彻底清缴，恐有后患，本宗弟子近日繁于事务，可否请贵宗出手相助？",
[1755]="寒铁铸剑",
[1756]="[ZM]近日打算炼制一柄寒铁宝剑，奈何门中库存不足，如有相赠者，本宗必有酬谢",
[1757]="虎岳试剑",
[1758]="虎岳试剑乃是本门传统，门中弟子须击败一头虎妖，方才通过试验，但若虎妖实力过强，亦不宜试剑。可否请贵宗前去杀一杀这些虎妖的锐气，以便本门弟子试剑",
[1759]="门中弟子急需玄铁以铸炼仙剑，奈何库房中竟无库存，如有相赠者，本宗定有酬谢",
[1760]="宗门比剑",
[1761]="青云剑阁以剑为尊，若贵宗可与本宗弟子比试一番，顺带指点剑法，便感激不尽了",
[1762]="精炼仙剑",
[1763]="[ZM]需要一批精炼石以精炼仙剑，如有相赠者，本宗定有重酬",
[1764]="魔修伏击",
[1765]="本宗近日有一队弟子惨遭魔修伏击，死伤惨重，此仇不报，枉为剑修，必须将他们一网打尽！",
[1766]="鬼物肆虐",
[1767]="魔修虽除，但其制造的鬼物仍在肆虐，若不除掉这些鬼物，必将后患无穷",
[1768]="弟子负伤",
[1769]="本宗被魔修伏击的弟子近日伤势愈发恶化，急需几颗蓝色品质的疗伤丹，如有相赠，本宗感激不尽",
[1770]="剑斩妖魔",
[1771]="没想到这群魔修竟然还留有后手，偷偷炼制了一头强悍的鬼王，此物不除，后患无穷，望贵宗与本门共同征讨，不可放过任何一头鬼物",
[1772]="为安置受通天江水患影响的灾民，[ZM]耗费了大量灵石，近来库房灵石竟已见底，若可送来一批灵石用于周转，学宫必有酬谢",
[1773]="惩戒门生",
[1774]="近日有一群被逐出学宫的书生，不学无术，在天云州偏远地区欺男霸女，必须施以惩戒，维护学宫的颜面",
[1775]="教化众生",
[1776]="近日天云洲中有山匪作乱，他们身负一定修为，却不经教化，实乃学宫之失，须将他们抓捕回来，好好教化",
[1777]="灵木作纸",
[1778]="近日门中洛阳纸贵，以至用于造纸的灵木紧缺，学宫不可一日无纸，若能提供一批灵木，学宫必有酬谢",
[1779]="玄羽作笔",
[1780]="既有好纸，怎能没有好笔，然而如今还缺几个玄鹤羽用作笔翎，若能提供此物，学宫必有酬谢",
[1781]="灵龟作砚",
[1782]="好笔配好砚，唯有以灵龟的龟壳打造的砚台，方能配得上这支好笔，若贵宗能捕捉一头灵龟回来，学宫感激不尽",
[1783]="寒烟为墨",
[1784]="提交10个寒烟玉",
[1785]="文房四宝，笔墨纸砚，如今还剩最后一件——墨。须以寒烟玉研磨，方能磨出最细腻的墨，若贵宗可提供此物，学宫必有重谢",
[1786]="符纸紧缺",
[1787]="提交30000符纸",
[1788]="文房四宝皆已具备，门中弟子正欲画几张符箓，却发现库房中的符纸不足了，不知贵宗可否提供一些符纸，学宫感激不尽",
[1789]="正气凛然",
[1790]="符箓已经画好，还须一些鬼物来试验符箓是否有效，麻烦贵宗去收服一些鬼物回来，学宫必定涌泉相报",
[1791]="因之前大祭司的所作所为，如今九黎部落中仍有不少信奉天魔的余孽，必须清理门户，以免重蹈覆辙",
[1792]="救死扶伤",
[1793]="曾受天魔邪气影响，九黎部落如今伤员众多，急需几颗蓝色品质的疗伤丹医治，如有相赠者，感激不尽",
[1794]="内忧外患",
[1795]="内忧未除，外患又至，九黎部落如今衰弱不堪，引得其他南疆部落虎视眈眈，有好斗的部落勇士前来挑衅，望贵宗出手相助",
[1796]="百废俱兴",
[1797]="九黎部落如今百废俱兴，急需大量灵木，然而部落中库存早已见底，若能提供一批灵木，部落感激不尽",
[1798]="魔修余孽",
[1799]="南疆如今仍有一部分魔修余孽，在暗中策划着针对九黎部落的阴谋，若不能斩草除根，他日必有后患",
[1800]="修复图腾",
[1801]="提交10个养魂木",
[1802]="九黎部落的图腾在之前的动乱中亦遭损毁，如今亟待修复，然而修复图腾还差养魂木这一珍贵材料，不知贵宗可否提供此物？",
[1803]="南疆仍有大量的妖兽作乱，若不能将其剿灭，九黎部落难以重新振兴，望贵宗出手相助",
[1804]="[ZM]一名土灵根弟子炼体遭遇瓶颈，急需土行之气以突破瓶颈，如有相赠者，必有酬谢",
[1805]="精炼法器",
[1806]="工欲善其事必先利其器，[ZM]急需上品精炼石用于精炼装备，奈何部落中库存不足，如有相赠者，部落定有酬谢",
[1807]="断除魔孽",
[1808]="在过往大祭司的领导下，九黎部落曾与魔修同流合污，如今是时候彻底斩断这段孽缘，一举将残余魔修统统剿灭了",
[1809]="入魔刀修",
[1810]="千刃门的入魔刀修时常前来袭扰风雪山庄，不给他们一点教训，风雪山庄将不得安宁，望贵宗出手相助",
[1811]="金砂铸刀",
[1812]="提交10个金阳砂",
[1813]="[ZM]急需几个金阳砂以铸炼宝刀抵御外敌，奈何天山不盛产此金石，不知贵宗可否提供此物？",
[1814]="斩除妖兽",
[1815]="天山妖兽强横无比，纵是有一定修为之士亦不敢轻易招惹，众多宝地被其占据，若能斩除一部分妖兽，本庄感激不尽",
[1816]="精炼宝刀",
[1817]="工欲善其事必先利其器，[ZM]急需凡品精炼石用于精炼宝刀，奈何庄中库存不足，如有相赠者，定有酬谢",
[1818]="鬼怪肆虐",
[1819]="由于千刃门的所作所为，如今天山鬼怪肆虐，并已逐渐逼近风雪山庄，望贵宗出手相助，本庄感激不尽",
[1820]="符箓可以镇压鬼物，奈何如今风雪山庄符纸紧缺，已无足够符纸制作符箓，若贵宗能提供一些符纸，本庄感激不尽",
[1821]="镇压鬼物",
[1822]="符箓已经制成，然可否对鬼物有效还须试验，若贵宗能收服一些鬼物用于试验，本庄感激不尽",
[1823]="火铜铸刀",
[1824]="提交10个火铜",
[1825]="以火铜铸炼的宝刀充盈炙阳之气，无论对鬼物还是天山的妖兽都有克制作用，奈何如今风雪山庄中火铜不足，若能提供此物，本庄感激不尽",
[1826]="斩杀妖魔",
[1827]="万事俱备，是时候去斩杀此地最难缠的妖魔了，此行凶险万分，可否请贵宗与本庄共同前往，协力斩除妖魔？",
[1828]="灵兽暴动",
[1829]="因千刃门的袭击所致，璇玑宫有一群灵兽被魔气影响，发生暴动，必须尽快将其降服，送回璇玑宫",
[1830]="璇玑宫中有不少弟子因此次千刃门袭击身负重伤，然而宫中疗伤丹早已耗尽，现急需几颗蓝色品质疗伤丹，若能提供此物，本宫必有酬谢",
[1831]="重建村落",
[1832]="璇玑峰有不少凡人村落在此次袭击中被毁，急需一批灵木用以重建村落，如有能提供灵木者，本宫必有酬谢",
[1833]="驱逐妖兽",
[1834]="因璇玑宫布下的阵法被千刃门所毁，如今有大量妖兽涌入璇玑峰，必须将其重新驱逐出去，方能保此地村民安危",
[1835]="修复阵法",
[1836]="被毁的阵法急需修复，然而用于修复阵法的矿石却已不足，若贵宗能提供一批矿石，本宫感激不尽",
[1837]="千刃魔修",
[1838]="千刃门魔修是贼心不改，又来擅闯璇玑峰，此次必须叫他们有来无回，望贵宗出手相助，与本宫一起迎战来敌",
[1839]="提交20个云露草",
[1840]="[ZM]急需几个云露草以炼制法宝抵御外敌，奈何此物在天山极为罕见，不知贵宗可否提供此物？",
[1841]="由于千刃门的所作所为，如今天山鬼怪肆虐，并已逐渐逼近璇玑宫，望贵宗出手相助，本宫感激不尽",
[1842]="火竹驱寒",
[1843]="提交10个火云竹",
[1844]="天山乃极寒之地，凡人若无驱寒之物则无法在此地生存，驱寒法阵须以火云竹布设，奈何如今宫中已无库存，不知贵宗可否提供此物？",
[1845]="斩杀鬼将",
[1846]="璇玑宫追朔到此地鬼怪的源头是一名鬼将，必须除掉这名鬼将，方可还此地一片安宁，此鬼将实力高强，望贵宗可与本宫协力应对",
