[2091]="仙商失联",
[2092]="前往玉京通报",
[2093]="你本想着去仙宫宝库看看有什么好货，却见守将正忙着接待一群风尘仆仆的仙商，那守将不时分心，神态有些焦躁，不知为何事烦扰。",
[2094]="前往玉京通报仙商失联一事",
[2095]="最后的消息",
[2096]="前往紫川坊市查探",
[2097]="仙宫商队失联之前，在名为紫川坊市的地方休整，并留下消息，此后便再无音讯，先去坊市中打探一番。",
[2098]="蛮兽突袭",
[2099]="往西面搜寻商队",
[2100]="坊市掌事说那日仙宫商队休整到离去，并未有异常，且商队护卫完备，按理说一般不会出事才对。如今只能往商队前去的西面搜寻。",
[2101]="望山远",
[2102]="那山不对劲……",
[2103]="你安排弟子们散开，大范围搜寻仙商踪迹，忽然，远处一座山引起你的注意……",
[2104]="蜃兽幻境",
[2105]="往前破解幻阵",
[2106]="本在幽冥之地的蜃兽，却莫名来此处布下大范围幻境，仙商很可能困在其中，你们决定将此大型幻境破除！",
[2107]="抵达雷山",
[2108]="继续破解幻阵",
[2109]="一路破阵诛妖，形势越加艰难，但总算抵达了雷山，但守卫在山下的蜃兽，神志清明，非寻常妖兽，看来不好对付……",
[2110]="战蜃王",
[2111]="进山讨伐蜃王",
[2112]="蜃王拘役了大量高阶修为的雷兽，在这座玄元铁山上做血祭大阵……此等暴行，其罪当诛！",
[2113]="归去葬山",
[2114]="查看战后情况",
[2115]="被抓的雷兽之中，仅雷奔存活下来，面对同族惨死，雷奔心生死志，祖师寻到他，问起今后的打算……",
[2116]="找到商队",
[2117]="与仙商执事对话",
[2118]="大型幻境已破去，你派弟子继续搜寻商队，果然找到了，只是他们已陷入麻烦之中……",
[2119]="回禀守将",
[2120]="与仙宫守将对话",
[2121]="成功解救仙商后，你与玉京众人，护卫仙商直到仙宫，守将看大家平安无事，甚是欢喜。",
[2122]="玉京赏功",
[2123]="此行帮了玉京不少忙，监正钧天子按例犒赏，却忽然聊起另一件事……",
[2124]="顽劣小仙",
[2125]="平定兽群骚乱",
[2126]="外出游历时，路过蓬莱，你正陶醉于此处盛景时，某处突然传来仙兽嘶鸣的嘈杂声音……",
[2127]="查看仙兽群异动",
[2128]="太有兴趣了",
[2129]="原来是一名调皮仙子在捣乱，令人奇怪的是，此人身为蓬莱仙子，却擅用魔功，令你不由心生好奇。",
[2130]="莫造次",
[2131]="受紫洛娘娘所托，你带着澄心前往九渊，只是不知道这个调皮的小妮子，又会惹出什么事情来。",
[2132]="活了一个",
[2133]="与乌霜对话",
[2134]="澄心平时脑子活络，但遇到不苟言笑的乌霜时，却变得支支吾吾，真不知道她这样能不能加入影卫司。",
[2135]="坊市与“羊”",
[2136]="前往地下坊市",
[2137]="澄心接下乌霜的任务后，前往一处地下坊市，在她还没加入影卫司前，还是要继续守护她的周全，毕竟答应过紫洛娘娘的。",
[2138]="放“羊”",
[2139]="解开被困修士禁制",
[2140]="你们带着被抓一众修士，硬闯出地下坊市，而这些修士身上说不定还有阴毒的禁制，需尽快解除。",
[2141]="澄心",
[2142]="你带着澄心，隐秘身形踪迹，确定没有地下坊市的手尾后，才回到镇渊府，向乌霜汇报。",
[2143]="一张大网",
[2144]="前往镇渊府集合",
[2145]="地下坊市不过是黑暗的冰山一角，对于真正的黑暗，一张大网已经打开……",
[2146]="道貌岸然",
[2147]="前往正阳宗山门",
[2148]="\"你带着澄心，跟随三大势力军阵，前往正阳宗，这个曾经的\"正道中坚\"，暗处到底做过些什么……\"",
[2149]="与她说",
[2150]="与澄心对话",
[2151]="你带着澄心，手刃仇敌，而后随队回到镇渊府，此时小妮子似乎……眼神更加坚定、澄澈了……",
[2152]="回禀蓬莱",
[2153]="此行顺利完成紫洛娘娘所托，你前往蓬莱拜访，告知澄心一切都好，而娘娘却说起另一件事……",
[2154]="诡异魔物",
[2155]="近来，有魔物莫名出现在仙界各处，造成一片破坏后，又消失不见，颇为诡异。九渊影卫司似乎查到了线索，前去问问。",
[2156]="隐秘洞窟",
[2157]="前往第一处线索",
[2158]="来到第一处线索处，此处山石嶙峋，杂草丛生，在某个隐秘处，竟是一个黑黝黝的洞窟。",
[2159]="幽深水潭",
[2160]="前往第二处线索",
[2161]="来到第二处线索处，此地有一处水潭，冒出冷冽寒气，最奇怪的是，那水潭却不结冰，且连你也看不透水潭有多深……",
[2162]="虚空魔窟",
[2163]="前往最后一处线索",
[2164]="抵达最后一处位置，眼前却只有广袤云海，风声萧瑟，流云翻腾，再没有别的东西了。",
[2165]="毁去节点",
[2166]="毁去空间节点",
[2167]="此处虚空节点已被魔物所知，为免往后再被利用，需布阵将节点彻底破坏！",
[2168]="回禀尊候",
[2169]="将那隐匿的空间节点、传送的寒晶魔阵破除后，果然不再有莫名出现的魔物，四处破坏仙界。",
[2170]="三尊齐聚",
[2171]="击败魔界先锋",
[2172]="今日一支魔界先锋入侵仙界，意图打探天兵的东西，必先将其剿灭，为反攻魔界扫清障碍。",
[2173]="回去向仙帝复命",
[2174]="山雨欲来",
[2175]="提交10枚炼灵丹（紫）",
[2176]="反攻魔界在即，可仍有一批军需亟待筹备，望祖师可为仙帝分忧。",
[2177]="万事俱备",
[2178]="如今反攻魔界已万事俱备，仙帝召集众人前往仙宫商议，请祖师赴会。",
[2179]="仙界历史·一",
[2180]="提交1壶灵泉秘酒",
[2181]="弟子们偶遇一名钓鱼老翁，其似乎对仙界历史颇为了解，只是需要弟子们带一些酒来，他才愿意畅谈。",
[2182]="回去将酒交给钓鱼翁",
[2183]="仙界历史·二",
[2184]="提交1壶浓郁酱香",
[2185]="弟子们再遇钓鱼翁，其又让弟子们找一壶酒来继续畅谈仙界历史",
[2186]="仙界历史·三",
[2187]="提交1个酒酿灵鱼",
[2188]="弟子们再遇钓鱼翁，其聊仙界历史的过程中竟然睡着了，弟子们须找一样食物来将其唤醒。",
[2189]="回去将灵鱼交给钓鱼翁",
[2190]="紧要之事",
[2191]="与瑶光仙子聊聊",
[2192]="仙魔两界之间局势愈发紧张，今日瑶光见你时，亦是神情严肃。",
[2193]="天衣阁",
[2194]="前往天衣阁",
[2195]="天衣阁看似寻常成衣铺，实是仙帝在三千世界布下的情报之所。",
[2196]="粉衣绣娘",
[2197]="寻找接头人",
[2198]="只要找到接头人，对上了暗号，对方自然会知晓我们的身份。",
[2199]="莲心",
[2200]="与莲心交谈",
[2201]="既然已经找到接头人，便去与他们的阁主聊聊究竟是何事吧。",
[2202]="面见阁主",
[2203]="寻踪",
[2204]="寻找云逸下落",
[2205]="天衣阁派往魔界的密探云逸如今下落不明，遂请祖师相助。",
[2206]="击退魔修",
[2207]="千丝引",
[2208]="寻找云逸留下的线索",
[2209]="云逸失踪之地便在此处，仔细寻找说不定会有他留下的线索。",
[2210]="查看印记",
[2211]="云逸",
[2212]="向云逸获取情报",
[2213]="众弟子循着飞针指引，寻得云逸下落，然而此时的云逸已是不容乐观。",
[2214]="机密",
[2215]="与凡凡一同返回天衣阁",
[2216]="此机密非同小可，一旦泄露，必使仙魔两界格局颠覆。",
[2217]="返回天衣阁",
