[2320]="精炼宝铠",
[2321]="守将需2片岩龟坚鳞",
[2322]="守将最近在寻找一珍稀材料，所需数量不少，四处托人询问，不知是否凑齐了。",
[2323]="仙法残页",
[2324]="绘制仙法周天运转图",
[2325]="守将最近得一仙法残页，据说是上古仙法，然而残页晦涩难懂，令他头秃……",
[2326]="熬炼体魄",
[2327]="守将需2株丹羽花",
[2328]="守卫仙宫，需不断熬炼体魄，提升修为，方能震慑宵小，扬仙宫之威势！",
[2329]="扰人清净",
[2330]="规劝扰人的蛮牛",
[2331]="守将镇守仙宫殿前，维持此地秩序，近来似乎发生了什么事情，令他有些苦恼……",
[2332]="修行有成",
[2333]="与仙宫守将切磋",
[2334]="修行无岁月，匆匆千百载，然而想在斗法中取胜，还得在实战中历练！",
[2335]="袍泽之谊",
[2336]="送手信给守将故友",
[2337]="每个人大抵都有一份过往，一份牵挂。",
[2338]="烈刀子",
[2339]="前往壮士埋骨之地",
[2340]="一抔烈酒，祭天之灵。",
[2341]="了却鸿愿",
[2342]="待到仙界无垠，万物安生，了却鸿愿时。",
[2343]="猫毛毡",
[2344]="给予一片避水兽皮",
[2345]="瑶光仙子有事寻你，去看看她吧。",
[2346]="偷袭点心铺",
[2347]="出手教训精怪一番",
[2348]="赋闲一日，瑶光仙子正站在点心铺旁生气，恰逢你前往拜访。",
[2349]="偷书妖怪？",
[2350]="寻找丢失的书籍",
[2351]="行至一雨棚下，你见到瑶光仙子似乎正寻找些什么。",
[2352]="重塑玉镜",
[2353]="给予一块玉髓",
[2354]="听闻瑶光仙子玉镜破碎，你决定前往安慰。",
[2355]="走丢小兽",
[2356]="拯救小兽",
[2357]="瑶光仙子传讯寻你，听语气焦急万分。",
[2358]="顽皮猫猫",
[2359]="和顽皮猫猫斗智斗勇",
[2360]="摇光仙子正于一处风景优美之地休憩，你与其一同，却被其随行猫猫缠上。",
[2361]="嬉笑玩闹",
[2362]="享受短暂的休憩时光",
[2363]="和瑶光仙子一同休憩。",
[2364]="半日闲",
[2365]="帮助瑶光仙子",
[2366]="猫猫们正与瑶光仙子嬉戏，加入其中吧~",
[2367]="犒赏宗门",
[2368]="前往仙宫拜见仙帝",
[2369]="众谪仙重归仙界，不断壮大宗门，尤其以祖师为翘楚，故受仙帝召见。",
[2370]="神秘仙药园",
[2371]="前往仙药园",
[2372]="仙帝谋划，布局深远，谋划万里。其中，充足的灵草等资源，乃是成就大事的重中之重。",
[2373]="一份惊喜",
[2374]="转交赏赐给瑶光仙子",
[2375]="仙宫内外，常常见到瑶光仙子忙碌的身影，仙帝有感，便想给仙子一份小礼。",
[2376]="神秘分身",
[2377]="前往搭救神秘人",
[2378]="仙帝坐镇于仙宫，却能对仙界万万里疆域，洞若观火，无所不察，其中便有神秘分身的功劳……",
[2379]="闲暇兴致",
[2380]="仙帝需2个沉水木",
[2381]="仙帝枯坐于仙宫御座，偶尔也会寻些小玩意，打发打发时间。",
[2382]="再遇分身",
[2383]="与仙帝分身碰面",
[2384]="仙帝分身遍布各处，为仙帝本体效力，其中一位，似乎遇到了麻烦……",
[2385]="为何而坐",
[2386]="仙帝御座，乃是守护整个仙界地域的阵眼所在，陛下施以上古仙法，坐镇于御座，燃烧自身维持阵法，守护着仙界安生！",
[2387]="梦回上古",
[2388]="上古仙魔一战，无数古仙陨落，仙界失去大量位面领土，而唯一存下的古仙——仙帝，在此后一直护佑仙界。",
[2389]="魔界细作",
[2390]="寻找魔界细作",
[2391]="岳知行最近事务繁忙，近来有事寻你帮忙。",
[2392]="关心则乱",
[2393]="寻找玉拂樱",
[2394]="玉拂樱沉迷于山间风景，一时忘却时间，岳知行担忧师妹情况，便委托你前去查看。",
[2395]="铸刃庚精",
[2396]="提交5块庚精",
[2397]="岳知行麾下一队伍兵器损毁，需要一些庚精。",
[2398]="绘河山",
[2399]="将玉京绘画入纸",
[2400]="岳知行在玉京观赏美景，希望能将其绘入纸中。",
[2401]="古怪修士",
[2402]="查看怪异修士",
[2403]="执法使汇报一修士举止怪异，和岳知行一同探究其想法。",
[2404]="他心神通",
[2405]="寻找莫知客",
[2406]="寻找莫知客，将其带到岳知行身旁。",
[2407]="难堪过往",
[2408]="等待莫知客施展神通",
[2409]="莫知客施展神通，了解恒秋内心所想。",
[2410]="数罪并罚",
[2411]="击败鬼物",
[2412]="派遣弟子跟随岳知行击败禁地鬼魂，拯救恒秋的友人。",
[2413]="鉴微镜",
[2414]="为莫知客寻些材料",
[2415]="莫知客听闻世间有一奇物，名曰鉴微镜，心中大动，遂生自制之念。",
[2416]="给莫知客一些材料",
[2417]="祸从口出",
[2418]="上前一探",
[2419]="仙街之上，遥见莫知客，正被一群修士团团围住，那些修士面色不善，只怕有危险",
[2420]="少年烦恼.一",
[2421]="问询岳知行",
[2422]="弟子们游访玉京，偶遇岳知行，见他行色匆匆，眉头紧锁，似是在找寻着什么",
[2423]="少年烦恼.二",
[2424]="救下莫知客",
[2425]="忽闻不远处传来一阵骚动，一群仙鹤惊飞而起，隐约传来少年求救的声音",
[2426]="少年烦恼.三",
[2427]="跟上莫知客",
[2428]="莫小哥不善斗法争锋，若放着不管，恐怕他又会有危险",
[2429]="跟随莫知客",
[2430]="少年烦恼.四",
[2431]="与王陌玉聊聊",
[2432]="解铃还需系铃人，不妨找当日那位修士了解一下情况",
[2433]="少年烦恼.五",
[2434]="你们被王陌玉当成了外包，一通忙碌之后，他总算愿意说出缘由",
[2435]="少年烦恼.六",
[2436]="探访莫知客",
[2437]="莫知客的心结不知有没有解开，不如去玉京探访一下",
[2438]="书中所载",
[2439]="“拜访玉拂樱”",
[2440]="你闲来无事，便打算拜访玉拂樱。",
[2441]="狂热书粉.一",
[2442]="询问玉拂樱情况",
[2443]="玉拂樱似有困惑，前去查看。",
[2444]="狂热书粉.二",
[2445]="搞定狂热书粉",
[2446]="玉拂樱正受困于狂热书粉，帮助其脱困。",
[2447]="做贼心虚",
[2448]="和岳知行交谈",
[2449]="岳知行正为话本一事愁眉苦脸，而玉拂樱正在不远处观望着...",
[2450]="拂樱的邀约",
[2451]="玉拂樱有事相求，去赴约吧。",
[2452]="三界撰事.一",
[2453]="玉拂樱在山上等你，和她会和吧。",
[2454]="三界撰事.二",
[2455]="教训小鬼",
[2456]="鬼界酆都，行船于忘川，忽闻水下声响，有小鬼闹事，请稳住船只。",
[2457]="三界撰事.三",
[2458]="一同吃火锅",
[2459]="短暂的歇脚，却见玉拂樱拿出锅碗，寻些食材便要开锅。",
[2460]="守望相助",
[2461]="前往玉京行天司",
[2462]="自回归仙界以来，与玉京诸位守望相助，不论公事亦或私交，都传出许多佳话。",
[2463]="天骄之骄",
[2464]="与莫知客切磋",
[2465]="凡是天纵奇才，常称为天骄，这一骄字，却各人有各自的含义。",
[2466]="不尊正道",
[2467]="\"捉拿真仙\"司马鸩\"\"",
[2468]="真仙者虽是修为圆满，然而大道三千，求索各异，真仙者，或有不尊正道之徒。",
[2469]="知行合一",
[2470]="与岳知行聊聊",
[2471]="行天司大师兄岳知行，辅助监正主持事务，统领执法使坚守正道，在仙界已有躬行君子的美名。",
[2472]="天地舆图",
[2473]="听闻钧天子得了一副《天地舆图》，深受其本人喜爱，不知这幅图，妙在何处？",
[2474]="行天秘闻",
[2475]="与玉拂樱聊聊",
[2476]="玉拂樱著书立传，以考究详实闻名，而在钧天子处，便有大量仙界秘闻，可供其查阅。",
[2477]="玉京论剑",
[2478]="与监正弟子切磋",
[2479]="钧天子手中持剑，却藏锋于内，经无尽岁月沉淀，其剑道修为如何，已无人知晓。或许与他弟子切磋，能看出一二来。",
[2480]="半步天道",
[2481]="钧天子以修行无情天道闻名于仙界，然而却有所牵挂，未能圆满，人称：半步天道！",
[2482]="拨浪鼓",
[2483]="帮帮梦蝶仙子",
[2484]="弟子们拜访蓬莱，恰见着那熟悉的紫色蝶影在花间徘徊，似乎似在寻找着什么。",
[2485]="帮帮迷糊的小梦蝶",
[2486]="珍贵之物.一",
[2487]="救下梦蝶仙子",
[2488]="闻云径深处传来一阵微弱呜咽之声，梦蝶仙子似乎遭遇了什么危险。",
[2489]="珍贵之物.二",
[2490]="与梦蝶仙子聊聊",
[2491]="梦蝶独自出蓬莱，似乎在寻找什么要紧事物，问问她是否需要帮忙？",
[2492]="珍贵之物.三",
[2493]="寻找制造材料",
[2494]="弟子循着古籍指引，寻遍山谷，终在一处幽深溪谷处觅得所需之物。",
[2495]="寻找材料之一",
[2496]="珍贵之物.四",
[2497]="弟子循着古籍指引，寻遍山谷，终在一处隐秘之所觅得所需之物。",
[2498]="寻找材料之二",
[2499]="珍贵之物.五",
[2500]="想办法从小仙灵手中讨得材料",
[2501]="寻找材料之三",
[2502]="珍贵之物.六",
[2503]="烧制茶盏",
[2504]="三样材料均已寻到，需按古法烧制那‘九霄琉璃盏’",
[2505]="珍贵之物.七",
[2506]="看看梦蝶如何了",
[2507]="所谓的‘九霄琉璃盏’原来在仙界随处可见，但这也是梦蝶仙子的一番心意。",
[2508]="看看梦蝶的情况",
[2509]="茶道之好",
[2510]="给梼老带些花草茶",
[2511]="听闻梼老最近醉心于茶道，恰好灵田新产了些新鲜花茶，不如给梼老送些过去",
[2512]="给梼老带些云露草",
[2513]="身体康健",
[2514]="给梼老带些药材",
[2515]="给梼老拿些药材",
[2516]="蓬莱顶流.一",
[2517]="细问详情",
[2518]="蓬莱近日张灯结彩，处处洋溢着喜庆之气，好不热闹，瞧瞧是何事",
[2519]=" 询问步染尘",
[2520]="蓬莱顶流.二",
[2521]="探望梼老",
[2522]="闻听一向康健的梼老病倒了，前去探望一番",
[2523]="看望梼老",
[2524]="蓬莱顶流.三",
[2525]="重新布置会场",
[2526]="弟子们带着梼老交予的图纸，来到设宴会场。然而，会场内却一片混乱",
[2527]="布置会场",
[2528]="蓬莱顶流.四",
[2529]="找回摸鱼的小妖灵们",
[2530]="梼老交代的庆典材料迟迟未能齐备，派遣出去的小妖灵们一个都没回来",
[2531]="捉回小妖灵们",
[2532]="蓬莱顶流.五",
[2533]="与梼老聊聊",
[2534]="在弟子们不再时，会场再度变得一片狼藉。梼老也忍不住拖着病体前来",
[2535]="蓬莱顶流.六",
[2536]="为梼老医治",
[2537]="一旦梼老不在，小妖灵们又恢复了散漫的状态，看来解铃还须系铃人",
[2538]="为梼老治疗",
[2539]="贪玩乐",
[2540]="“上前一探”",
[2541]="你闲来无事，便在蓬莱里闲逛，偶遇一金光小龙于树冠上徘徊。",
[2542]="孔雀开屏",
[2543]="和敖祝交流",
[2544]="蓬莱一孔雀灵兽行为异常，敖祝邀请你前来调查一番。",
[2545]="蓬莱散人",
[2546]="击败闹事散修",
[2547]="有一散人正于仙岛闹事，敖祝不便出手，便请求你的帮助。",
[2548]="食材告罄",
[2549]="支援蓬莱灵草3万",
[2550]="蓬莱的灵兽缺些食物需要你支援。",
[2551]="盛情难却",
[2552]="敖祝为感谢你们对蓬莱的帮助，特意邀请你们到蓬莱一聚。",
[2553]="繁花似锦",
[2554]="提交丹羽花一份",
[2555]="最近小仙子们心情不佳，敖祝为此特意寻你帮忙，找些小礼物送给小仙子们，恢复其心情。",
[2556]="养神丹药",
[2557]="提交炼灵丹三份",
[2558]="紫洛仙子日理万机，敖祝见其操劳，便想送些养神丹药给她，既表关心，又能助其恢复精神。",
[2559]="独在异乡？",
[2560]="带着敖祝寻找族人",
[2561]="敖祝似乎心情不好，去看看它吧。",
[2562]="装饰之物",
[2563]="紫洛请弟子们寻些鲜艳的花草",
[2564]="新的爱好",
[2565]="为紫洛寻几个牌友",
[2566]="近日紫洛迷上了马吊牌，一缺三。为了不让紫洛霍霍自己的弟子，为她找几个牌友",
[2567]="参天灵木.一",
[2568]="寻访蓬莱",
[2569]="近日蓬莱的通天灵木似乎有异，紫洛邀你自紫云宫一叙。",
[2570]="参天灵木.二",
[2571]="奉上赠礼",
[2572]="紫洛娘娘传讯,邀你一叙。",
[2573]="参天灵木.三",
[2574]="叩问树灵",
[2575]="你带弟子们来到通天灵木前，只见巨木参天，枝叶却略显枯黄，隐约透出一丝衰败之气。",
[2576]="参天灵木.四",
[2577]="叩问仙界众灵",
[2578]="噬灵虫虽已除去，但通天灵木的生机之源仍在不断外溢，若要彻底解决，还需寻其根源。",
[2579]="参天灵木.五",
[2580]="捣毁祭坛",
[2581]="你与弟子们循着线索，寻至一处隐秘山谷，阴风呼啸，一座黑色祭坛矗立中央，刻满诡异符文，邪气森然。",
[2582]="参天灵木.六",
[2583]="传讯给紫洛",
[2584]="虽然将祭坛捣毁，此境生机之源不断流失。双全之法……唯有紫洛可解。",
[2585]="狱中魔影",
[2586]="教它做人",
[2587]="行至九渊狱中，偶遇一怪魔挑衅。",
[2588]="教这魔物做人",
[2589]="欺软怕硬",
[2590]="点拨教化",
[2591]="哞似乎还不服气，此后每次你至九渊监牢时，它总是暗中煽动其它囚徒，挑起争端。",
[2592]="贪财之物",
[2593]="分点好处给它",
[2594]="哞近日手头有点紧，不妨去看看它。",
[2595]="给哞分点好处",
[2596]="威武五十",
[2597]="威武50看看实力",
[2598]="哞近日手头有点紧，想看看祖师是否有实力。",
[2599]="给它瞧瞧祖师的实力",
[2600]="逆天改命.一",
[2601]="一探究竟",
[2602]="弟子们途径九渊附近，忽见一诡异暗影。",
[2603]="看看哞究竟作何",
[2604]="逆天改命.二",
[2605]="帮哞寻找那本绝世功法",
[2606]="哞提及自己正在寻找，一本逆天改命得神奇功法。",
[2607]="帮哞解开线索",
[2608]="逆天改命.三",
[2609]="寻找《逆命之书》",
[2610]="根据线索，弟子们前往衔接黑市一探究竟。",
[2611]="逆天改命.四",
[2612]="把书交给哞",
[2613]="花重金求得《逆命之书》，把它交给哞吧。",
[2614]="失踪魔鸢",
[2615]="寻找魔鸢踪迹",
[2616]="近日乌霜派遣出去的魔鸢在境内失去了联系，恐怕有魔界细作混入仙界边境",
[2617]="向乌霜复命",
[2618]="九渊之花",
[2619]="提交1朵<color=#76d81e>丹羽花</color>",
[2620]="九渊之地，魔气浓郁，极少有鲜花绽放。近日乌霜在寻找一些能在九渊存活的花种",
[2621]="将花交予乌霜",
[2622]="剪除叛徒",
[2623]="击败魔界细作",
[2624]="乌霜请求你协助九渊，抓捕细作。",
[2625]="归乡之舟·一",
[2626]="打探消息",
[2627]="你行至九渊，偶然看到乌霜似乎正在寻找着什么",
[2628]="寻找乌霜遗落的纸船",
[2629]="归乡之舟·二",
[2630]="寻找纸船",
[2631]="听闻那只破旧的纸船，乌霜格外珍惜，帮她找找",
[2632]="归乡之舟·三",
[2633]="与乌霜聊聊",
[2634]="你决定将纸船带给乌霜，与她聊聊。",
[2635]="归乡之舟·四",
[2636]="赴约",
[2637]="你与乌霜约定三日后再相见",
[2638]="归乡之舟·五",
[2639]="陪乌霜祭拜",
[2640]="乌霜邀请你前往青冥的墓前，一同为其祭拜",
[2641]="陪伴乌霜",
[2642]="整顿军备",
[2643]="黩武需10万玄铁",
[2644]="炼制九渊仙军的铠甲兵器，所需玄铁不足，若能提供支援，军中自有酬谢！",
[2645]="以战为尊",
[2646]="与九渊将领切磋",
[2647]="九渊军中，以战为尊，黩武身为九渊统领，自然更看中实力！",
[2648]="抵御魔族",
[2649]="破坏破虚裂隙",
[2650]="示敌以弱，乃是仙界谋划，倘若中了计，便会有轻视、欺压。",
[2651]="擅离职守",
[2652]="找回九渊将士",
[2653]="九渊仙军以军纪严明著称，若犯禁，必受罚。",
[2654]="戍边大阵",
[2655]="黩武需2万阵石",
[2656]="仙魔交界处，需搭建巨型阵法，方能在两军对垒时，辅佐本军仙将冲锋杀敌！",
[2657]="行军演阵",
[2658]="在镇渊府演阵",
[2659]="为将者，谋划千里，行军演阵，决胜于千里之外！",
[2660]="业障缠身",
[2661]="黩武需2片寒蚌雪壳",
[2662]="以往犯下的业障，在发生那时，便再也脱不开身。",
[2663]="尚武之军",
[2664]="观礼九渊演武",
[2665]="尚武之军，尚武一界，九重九天，莫敢来犯！",
[2666]="新制收藏",
[2667]="为其寻几尾<color=#76d81e>七色雀羽</color>",
[2668]="九幽候虽藏镜无数，却独缺彩羽所制。得此，方算圆满。",
[2669]="低调奢华",
[2670]="寻2枚<color=#76d81e>岩龟坚鳞</color>",
[2671]="九幽候欲打造一副新镜框，需得低调中见奢华。寻找一种鳞片，质地坚硬，耐磨经久，且自带天然光泽。",
[2672]="所集珍藏",
[2673]="前往九渊赴约",
[2674]="九幽侯感念你此前相助，特邀请你参观他的藏品阁。",
[2675]="天地如棋.一",
[2676]="近日九渊似有异动，仙帝以饮茶为由邀你前来，其实另有交代。",
[2677]="天地如棋.二",
[2678]="陪九幽候下棋",
[2679]="对于你的探访，九幽侯殷勤备至。热情邀请你与他手谈一局。",
[2680]="天地如棋.三",
[2681]="夜探九渊东南方位",
[2682]="九幽候白日似乎暗有所指。子夜，你隐匿身形，夜探九渊东南隅。",
[2683]="天地如棋.四",
[2684]="设法突围",
[2685]="你夜探九渊，不想中了算计，身后九渊叛众对你穷追不舍，得设法突围。",
[2686]="天地如棋.五",
[2687]="与九幽侯对弈",
[2688]="既然九幽候拿你当刀使，那你也不得不展现真正的实力了！",
[2689]="忆往昔",
[2690]="到东湖君府上一叙",
[2691]="尤记得，通天江上，金龙横空，有德者飞升，使万民同贺！",
[2692]="缉拿祸首",
[2693]="缉拿迦楼罗妖鸟",
[2694]="东湖君为行天司效力，在抓捕犯人时，他似乎遇到了困难。",
[2695]="雷罚审讯",
[2696]="协助审讯犯人",
[2697]="雷罚神山，乃是玉京司审讯囚犯之地，东湖君似乎遇到了棘手的犯人……",
[2698]="淬炼血脉",
[2699]="东湖君需2枚龙血玉",
[2700]="真龙之躯便是东湖君最强的攻伐法器，以珍稀材料淬炼龙躯，使其威能更盛！",
[2701]="罪人遗子",
[2702]="前去查看罪人遗子",
[2703]="前人作罪，后人遭殃。",
[2704]="府上作客",
[2705]="受邀去东湖府上做客",
[2706]="好友相聚，一壶清茶，一盒点心，便是谈不完的话头。",
[2707]="珍藏古物",
[2708]="帮东湖君破解石盒",
[2709]="东湖君喜好年代久远的古物，最近，他得到了一个奇怪难解的物件……",
[2710]="回望大江",
[2711]="感应凡界通天江",
[2712]="东湖君还记挂着下界通天江的百姓，或许以祖师神通，能帮得上忙。",
[2713]="染血纸鸦.一",
[2714]="前往玄霜阁拜访",
[2715]="仙界名门玄霜阁似与魔界暗中有所勾连。不妨登门拜访，探查虚实。",
[2716]="染血纸鸦.二",
[2717]="玄霜阁勾连魔界证据尚未确凿,却惨遭灭门，此事需找乌霜聊聊。",
[2718]="无鞘之刃",
[2719]="避开此人杀招",
[2720]="行至九渊地界，忽觉一阵阴风裹挟着凛冽杀机，向你骤然袭来。",
[2721]="有事相求.一",
[2722]="无名需要2片<color=#76d81e>岩龟坚鳞</color>",
[2723]="这段时日无名被罚闭关思过，闲来无事，打算研究一些东西。",
[2724]="有事相求.二",
[2725]="无名需要一些<color=#76d81e>金蚕灵丝</color>",
[2726]="不可言说.一",
[2727]="寻找暗探踪迹",
[2728]="影卫司的一名成员行迹暴露，如今被魔界追捕。乌霜请求你救下那名同僚性命。",
[2729]="不可言说.二",
[2730]="阻止无名",
[2731]="最先找到夜枭的无名，却对自己的同僚起了杀心。",
[2732]="约法三章",
[2733]="你最终还是没忍心说出真相。将夜枭的遗物带回，交给了乌霜",
[2734]="仙宫醉汉.一",
[2735]="与那醉汉聊聊",
[2736]="行至仙宫，沿廊而行，忽闻一阵清冽酒香，转角处，见一醉汉向你招手。",
[2737]="仙宫醉汉.二",
[2738]="向瑶光仙子打听那醉汉",
[2739]="翌日，你再访仙宫，将昨日见闻讲予瑶光仙子。",
[2740]="酿酒材料.一",
[2741]="给予2枚<color=#76d81e>金焰果</color>",
[2742]="逍遥子正在寻找有趣的酿酒材料，不若去问问。",
[2743]="酿酒材料.二",
[2744]="给予3枝<color=#76d82e>青元芝</color>",
[2745]="逍遥子正在寻找有趣的酿酒材料，他保证不让你白跑腿。",
[2746]="一饭之恩",
[2747]="与那人攀谈",
[2748]="你偶行至凡界集市，熙攘的酒楼内人声鼎沸。那柜台后的一位酒商格外眼熟。",
[2749]="酒与剑",
[2750]="与逍遥子过两招",
[2751]="仙宫长廊，月色如水，清风徐来。忽见不远处廊下那醉汉，正向你招手。",
[2752]="何人识吾.一",
[2753]="随逍遥子同行",
[2754]="逍遥子邀请你一同随他下界走走，也不知他葫芦里卖的什么药。",
[2755]="何人识吾.二",
[2756]="为百姓祈雨",
[2757]="逍遥子化身万千，穿梭三界，行侠仗义，救苍生于水火。他邀你同行，正是为救此地黎民百姓。",
[2758]="守仙宫",
[2759]="“前往赴约”",
[2760]="天御卫统领云澈，邀您一叙。",
[2761]="凶神恶煞",
[2762]="和云澈交谈",
[2763]="有一修为强大的修士打伤了仙宫的守卫，云澈请求你出手惩戒。",
[2764]="心灵突击",
[2765]="恢复修士的神志",
[2766]="仙宫的深处，云澈遇到了些麻烦。",
[2767]="沧海遗珠",
[2768]="寻找沧海遗珠",
[2769]="你随着云澈来到深海中，此处有沧海遗珠的线索。",
[2770]="相柳之后",
[2771]="讨伐相柳之后",
[2772]="相柳，蛇身九头，食人无数，陨于昆仑，其后肆掠于世。",
[2773]="净化污血",
[2774]="寻得蕴雷兽骨",
[2775]="相柳污血污染地脉，大地生灵涂炭，云澈寻你商讨此事。",
[2776]="孔明锁",
[2777]="前往赴约",
[2778]="云澈于秘境得一奇物，特邀你一同研究。",
