[2783]="以1枚<color=#76d81e>地脉岩晶</color>修补镜面",
[2784]="步染尘心爱的浮光玉镜裂开了！步染尘心都快碎了，还得祖师相助！",
[2785]="岁月痕迹.一",
[2786]="步染尘需2朵<color=#76d81e>青元芝</color>",
